function canvasPointerMove(e){const p=screenPoint(e);$('#coordinates').textContent=`X ${Math.round(p[0])}  ·  Y ${Math.round(p[1])} mm`;if(!pointer)return;if(pointer.mode==='pan'){view.x=pointer.view.x+e.clientX-pointer.start[0];view.y=pointer.view.y+e.clientY-pointer.start[1];applyView();}else if(pointer.mode==='cadMove'){if(Math.hypot(e.clientX-pointer.screen[0],e.clientY-pointer.screen[1])<4&&!pointer.delta)return;pointer.delta=[p[0]-pointer.start[0],p[1]-pointer.start[1]];drawSelection();}else if(pointer.mode==='routeMove'){const dx=p[0]-pointer.start[0],dy=p[1]-pointer.start[1];if(!dx&&!dy)return;if(!pointer.saved){checkpoint();pointer.saved=true;}current().points=pointer.points.map(p=>[p[0]+dx,p[1]+dy]);changed();}else if(pointer.mode==='move'){const dx=p[0]-pointer.start[0],dy=p[1]-pointer.start[1];if(!dx&&!dy)return;if(!pointer.saved){checkpoint();pointer.saved=true;}const o=current();o.x=pointer.object.x+dx;o.y=pointer.object.y+dy;changed();}}
